 function snapshotLocation():ReadingLocation|null{if(!pdf||!viewer.current)return null;return {paperId:paperRef.current.id,documentId:documentRef.current,view:viewer.current.getViewState(),active,tab,readerTop:reader.current?.scrollTop||0,readerMode:readLocal('reader-mode','focus')};}
