 function saveFocus(panel:Panel){if(!focus)return;const current=paperRef.current.id===focus.paper.id?paperRef.current:papersRef.current.find(p=>p.id===focus.paper.id);if(!current?.analysis)return;const analysis={...current.analysis,sections:current.analysis.sections.map(s=>{if(s.id!==focus.sectionId)return s;const exists=s.figures.some(f=>f.id===focus.figure.id);const figures=exists?s.figures:[...s.figures,focus.figure];return {...s,figures:figures.map(f=>{if(f.id!==focus.figure.id)return f;const index=focus.panel?f.panels.findIndex(p=>p.label===focus.panel!.label):-1;return {...f,panels:index<0?[...f.panels,panel]:f.panels.map((p,i)=>i===index?panel:p)};})};})};void persist(revisePaper(current,analysis,'子图精读 '+panel.label));setToast('子图与详细解析已保存');}
